// Turns web/dist (one app.js + one app.css) into src/app.generated.js, which the Worker imports.
// Run through `cd web && bun run build`. The generated file is committed, so deploys need no build step.
// The Worker serves the JS, the CSS and the fonts as files at /_app/<name>.<hash>.<ext> that browsers keep for a year
// (#351), so the per-visitor HTML stays small. The hash changes whenever the content does.
import {readFileSync, writeFileSync, existsSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dist = join(root, 'web', 'dist');
const hash = (s) => createHash('sha256').update(s).digest('hex').slice(0, 12);
const js = readFileSync(join(dist, 'app.js'), 'utf8');
let css = existsSync(join(dist, 'app.css')) ? readFileSync(join(dist, 'app.css'), 'utf8') : '';
// Fonts inlined as data: URLs become their own woff2 files, so the page policy needs no data: fonts.
const fonts = {};
css = css.replace(/url\((["']?)data:font\/woff2;base64,([A-Za-z0-9+/=]+)\1\)/g, (_, q, b64) => {
  const path = `/_app/font.${hash(b64)}.woff2`;
  fonts[path] = b64;
  return `url(${path})`;
});
const jsPath = `/_app/app.${hash(js)}.js`;
const cssPath = `/_app/app.${hash(css)}.css`;
const out = '// GENERATED by scripts/embed-web.mjs from web/. Do not edit by hand.\n'
  + 'export const APP_JS = ' + JSON.stringify(js) + ';\n'
  + 'export const APP_CSS = ' + JSON.stringify(css) + ';\n'
  + 'export const APP_JS_PATH = ' + JSON.stringify(jsPath) + ';\n'
  + 'export const APP_CSS_PATH = ' + JSON.stringify(cssPath) + ';\n'
  + '// woff2 files, base64.\n'
  + 'export const APP_FONTS = ' + JSON.stringify(fonts) + ';\n';
writeFileSync(join(root, 'src', 'app.generated.js'), out);
console.log('app.generated.js:', Math.round(out.length / 1024), 'KB (js ' + Math.round(js.length / 1024) + ' KB, css ' + Math.round(css.length / 1024) + ' KB, ' + Object.keys(fonts).length + ' fonts)');
